import json, sqlite3
from pathlib import Path

setup = '''CREATE TABLE invoices (id INTEGER PRIMARY KEY, total_cents INTEGER NOT NULL);
CREATE TABLE invoice_tags (invoice_id INTEGER NOT NULL, tag TEXT NOT NULL);
INSERT INTO invoices VALUES (1, 1000), (2, 1000), (3, 500);
INSERT INTO invoice_tags VALUES (1, 'priority'), (1, 'review'), (2, 'priority');'''
queries = {
    'join_duplicates_invoice': 'SELECT SUM(i.total_cents) FROM invoices i JOIN invoice_tags t ON t.invoice_id = i.id',
    'distinct_amount_discards_equal_invoice': 'SELECT SUM(DISTINCT i.total_cents) FROM invoices i JOIN invoice_tags t ON t.invoice_id = i.id',
    'exists_counts_each_tagged_invoice_once': 'SELECT SUM(i.total_cents) FROM invoices i WHERE EXISTS (SELECT 1 FROM invoice_tags t WHERE t.invoice_id = i.id)',
}
expected = dict(zip(queries, [3000, 1000, 2000]))
with sqlite3.connect(':memory:') as db:
    db.executescript(setup)
    actual = {name: db.execute(sql).fetchone()[0] for name, sql in queries.items()}
if actual != expected:
    raise SystemExit(f'Unexpected results: {actual!r}')
result = {'scope': 'Fictional offline SQLite tutorial control, prepared by autonomous AI agents. No customer or editorial acceptance evidence.', 'problem': 'Sum invoice totals once per invoice that has at least one tag. Exclude untagged invoices.', 'sqlite_version': sqlite3.sqlite_version, 'setup_sql': setup, 'queries': queries, 'expected_cents': expected, 'observed_cents': actual}
output = Path('products/services/editorial-sqlite-controls/invoice-tag-totals.json')
output.parent.mkdir(parents=True, exist_ok=True)
output.write_text(json.dumps(result, indent=2) + '\n', encoding='utf-8')
print(output.read_text(encoding='utf-8'))
